# Cars are now rented by the day; older weekly/monthly/yearly/per-trip car rentals keep an equivalent daily rate.
DAYS_PER_PERIOD = {"RENT_WEEKLY": 7, "RENT_MONTHLY": 30, "RENT_ANNUAL": 365, "PER_TRIP": 1}


def cars_to_daily_rates(apps, schema_editor):
    from decimal import Decimal, ROUND_HALF_UP
    CarListing = apps.get_model("marketplace", "CarListing")
    for car in CarListing.objects.filter(price_basis__in=DAYS_PER_PERIOD):
        days = DAYS_PER_PERIOD[car.price_basis]
        car.price_xaf = max(Decimal("1"), (car.price_xaf / days).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        car.price_basis = "RENT_NIGHTLY"
        car.save(update_fields=["price_xaf", "price_basis"])

